import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts, countedOn, statusOn } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn, liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/**
 * A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd), inclusive, whether
 * it is closed, the due-total fixed when it was closed ('' while open), and each person's due-total
 * fixed when it was closed, by person id (empty while open), and whether it is soft-closed: closed
 * with its figures fixed, but its claims can still be changed; and the fiscal year its from-date falls in.
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  personTotals: Record<string, string>;
  soft: boolean;
  /** The fiscal year its from-date falls in, FY<yyyy>. */
  fy: string;
  /** The most OPEN or PENDING claims a person may have in it ('' for no cap). */
  cap: string;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The period whose dates contain the date (yyyy-MM-dd), or null when none does. */
export function periodOf(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/**
 * A person's due-total for a period: the one fixed when it was closed (0.00 for a person added
 * after), else the due as shown now of their claims due by a date in it (a claim's period is the one
 * containing its due-by) that counted at the end of its last
 * day, by the status their log records then, added up.
 */
export function personPeriodDueTotal(
  period: Period,
  person: Person,
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.personTotals[person.id] ?? '0.00';
  return sumDue(
    claims
      .filter((c) => c.personId === person.id && countedOn(c, period.to, liveHolds(person, late.today), late.today) && period.from <= c.dueBy && c.dueBy <= period.to)
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date, c.id), floor, late, gradeOn(person.grades, c.date))),
  );
}

/**
 * A person's carried figure for a period: the due as shown now of their claims that count and belong
 * to a period (by due-by) ending before this one starts, and were still OPEN or PENDING at the end of
 * this period's last day by the status their log records then, added up.
 */
export function personPeriodCarried(
  period: Period,
  periods: Period[],
  person: Person,
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  const holds = liveHolds(person, late.today);
  return sumDue(
    claims
      .filter((c) => {
        if (c.personId !== person.id) return false;
        const own = periodOf(periods, c.dueBy);
        if (own === null || own.to >= period.from) return false;
        const status = statusOn(c, period.to);
        return (status === 'OPEN' || status === 'PENDING') && countedOn(c, period.to, holds, late.today);
      })
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date, c.id), floor, late, gradeOn(person.grades, c.date))),
  );
}

/** A period's due-total: the people's due-totals for it, added up. */
export function periodDueTotal(
  period: Period,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  return sumDue(people.map((person) => personPeriodDueTotal(period, person, claims, rates, floor, late)));
}

/**
 * A period's classic due-total: the due-total fixed when it was closed, else the due as shown now
 * of the claims due by a date in it that count by their status now (OPEN, PENDING and SETTLED),
 * added up over everyone.
 */
export function classicPeriodDueTotal(
  period: Period,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.closedTotal !== '' ? period.closedTotal : periodDueTotal(period, people, claims, rates, floor, late);
  return sumDue(
    people.flatMap((person) =>
      claims
        .filter((c) => c.personId === person.id && counts(c, liveHolds(person, late.today), late.today) && period.from <= c.dueBy && c.dueBy <= period.to)
        .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date, c.id), floor, late, gradeOn(person.grades, c.date))),
    ),
  );
}
import { Fragment } from 'react';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useClaims } from '../claims/claims';
import { useRates } from '../rates/rates';
import { useFloor, useLate } from '../access/access';
import { personPeriodCarried, personPeriodDueTotal, usePeriods } from './periods';

function PersonPeriodsHead({ sheetId }: { sheetId: string }) {
  const periods = usePeriods(sheetId).data ?? [];
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <th>{p.name}</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}

// A person's due-total for each period on the sheet: live while the period is open, fixed when it
// was closed; and the figure carried into it from earlier periods.
function PersonPeriods({ sheetId, person }: { sheetId: string; person: Person }) {
  const periods = usePeriods(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  return (
    <>
      {periods.map((p) => (
        <Fragment key={p.name}>
          <td data-testid={`person-period-${p.name}-due-total`}>
            {personPeriodDueTotal(p, person, claims, rates, floor, late)}
          </td>
          <td data-testid={`person-period-${p.name}-carried`}>
            {personPeriodCarried(p, periods, person, claims, rates, floor, late)}
          </td>
        </Fragment>
      ))}
    </>
  );
}

export const contributions = [
  PersonHead.fill({ order: 22, Component: PersonPeriodsHead }),
  PersonRow.fill({ order: 22, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import type { Claim } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { personDueTotal, trimmedSumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';
import { personOverdue } from '../overdue/overdue';
import { floorOf, lateOf } from '../access/access';
import type { Settings } from '../access/access';
import type { Sheet } from '../sheet/sheet';

/** A sheet's own figures, as its header shows them: its people, its due-total and its overdue-total. */
export type Figures = { people: number; dueTotal: string; overdueTotal: string };

/** A sheet's figures from what it holds — the one working the header and the consolidated figures share. */
export function sheetFigures(
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  today: string,
  floor: Dated,
  late: Late,
  cap: string,
): Figures {
  const claimsOf = (id: string) => claims.filter((c) => c.personId === id);
  return {
    people: people.length,
    dueTotal: trimmedSumDue(
      people.map((p) => personDueTotal(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late, cap)),
    ),
    overdueTotal: trimmedSumDue(
      people.map((p) => personOverdue(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late).total),
    ),
  };
}

const enc = encodeURIComponent;

/**
 * A sheet's figures as it is now, every part of it read fresh from the store: the consolidated
 * figures are always the current ones, whatever as-of date the screen shows.
 */
async function readFigures(sheetId: string): Promise<Figures> {
  const [sheet, people, claims, rates, settings] = await Promise.all([
    getJsonNow<Sheet>(`/api/sheets/${enc(sheetId)}`),
    getJsonNow<{ people: Person[] }>(`/api/sheets/${enc(sheetId)}/people`).then((r) => r.people),
    getJsonNow<{ claims: Claim[] }>(`/api/sheets/${enc(sheetId)}/claims`).then((r) => r.claims),
    getJsonNow<{ rates: Rate[] }>(`/api/sheets/${enc(sheetId)}/rates`).then((r) => r.rates),
    getJsonNow<Settings>(`/api/sheets/${enc(sheetId)}/settings`),
  ]);
  return sheetFigures(people, claims, rates, sheet.today, floorOf(settings), lateOf(settings, sheet.today), settings.cap ?? '');
}

/**
 * The sheet's own figures as it is now, read while the screen shows it as of a date (otherwise the
 * screen's own reads are already the current ones).
 */
export function useFiguresNow(sheetId: string, enabled: boolean) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'figures-now'] as const,
    queryFn: () => readFigures(sheetId),
    enabled,
  });
}

/**
 * The figures of each of the sheet's descendants: the sheets naming it as their parent, theirs, and
 * so on. Kept under the sheet's own key, so loading the sheet again re-reads them all.
 */
export function useDescendantFigures(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants'] as const,
    queryFn: async () => {
      const { descendants } = await getJsonNow<{ descendants: string[] }>(`/api/sheets/${enc(sheetId)}/descendants`);
      return Promise.all(descendants.map(readFigures));
    },
  });
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { sumDue, useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useCap, useFloor, useLate } from '../access/access';
import { useAsOf } from '../sheet/asof.slot';
import { sheetFigures, useDescendantFigures, useFiguresNow } from './consolidated';

// The consolidated figures, over the sheet and all its descendants: everyone on them, and each
// sheet's due-total and overdue-total as that sheet shows them, added up. The sheet's own figures
// are the header's; with no children these are just those. They are always the current figures: while
// the screen shows the sheet as of a date, the sheet's own are read again as it is now.
function Consolidated({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const descendants = useDescendantFigures(sheetId).data ?? [];
  const [asOf] = useAsOf();
  const now = useFiguresNow(sheetId, asOf !== '').data;

  const own = asOf !== '' ? now ?? { people: 0, dueTotal: '0.00', overdueTotal: '0.00' }
    : sheetFigures(people, claims, rates, today, floor, late, cap);
  const all = [own, ...descendants];
  const count = all.reduce((n, f) => n + f.people, 0);

  return (
    <section data-testid="consolidated">
      Consolidated — People: <strong data-testid="consolidated-people-count">{count}</strong>{' '}
      Due: <strong data-testid="consolidated-due-total">{sumDue(all.map((f) => f.dueTotal))}</strong>{' '}
      Overdue: <strong data-testid="consolidated-overdue-total">{sumDue(all.map((f) => f.overdueTotal))}</strong>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -99.5, Component: Consolidated });

