import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { ASOF_PARAM } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The as-of date the signed-in user's screen reads the sheet at ('' for now). */
export const useAsOf = () => useSearchParam(ASOF_PARAM, asString);

// The as-of view: an entry, a set and a clear button, and the as-of date shown (nothing while
// unset). While it is set every cell on the screen reads the sheet as it stood at the end of that
// date (the server answers each read so), and every change is refused. It lives in this user's URL,
// so other users' screens are unaffected. Setting or clearing it re-reads everything.
function AsOfView() {
  const queryClient = useQueryClient();
  const [asOf, setAsOf] = useAsOf();
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const shown = useRef(asOf);
  useEffect(() => {
    if (shown.current === asOf) return;
    shown.current = asOf;
    void queryClient.resetQueries();
  }, [asOf, queryClient]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const date = input.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Choose a date to view the sheet as of.');
      return;
    }
    setAsOf(date);
  };

  return (
    <form onSubmit={submit} data-testid="asof-form">
      As of: <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      <label>
        View as of{' '}
        <input
          type="date"
          data-testid="asof-date"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="asof-set">
        Set
      </button>{' '}
      <button
        type="button"
        data-testid="asof-clear"
        onClick={() => {
          setError('');
          setAsOf(undefined);
        }}
      >
        Clear
      </button>
      {error && (
        <p role="alert" data-testid="asof-error">
          {error}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -99, Component: AsOfView });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx response, carrying its status so a caller can tell one refusal from another.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of date the screen reads the sheet at ('' for now): the `asof` search param. While it is set
// every read names it, so the server answers with the sheet as it stood then, and every change is
// refused here, never sent — the form that made it shows its usual error. Loading a sheet is no
// change: it only re-reads one.
export const ASOF_PARAM = 'asof';

function asOf(): string {
  return new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
}

function refuseWhileAsOf(method: string, path: string): void {
  if (asOf() !== '' && !path.endsWith('/load')) {
    throw new HttpError(`${method} ${path} -> refused while viewing as of ${asOf()}`, 409);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

// A read that depends on who is signed in names them too.
export function getJson<T>(path: string, user?: string): Promise<T> {
  const headers: Record<string, string> = {};
  if (user !== undefined) headers['X-User'] = encodeURIComponent(user);
  const date = asOf();
  if (date !== '') headers['X-As-Of'] = date;
  return send<T>(path, { headers });
}

// A read of the sheet as it is now, whatever as-of date the screen shows.
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change is made by the signed-in user: name them, and the server records who made it.
function jsonHeaders(user?: string): HeadersInit {
  return user === undefined
    ? { 'Content-Type': 'application/json' }
    : { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) };
}

export async function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  refuseWhileAsOf('POST', path);
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

// A change to the signed-in user's own preferences, not to any sheet: open while viewing as of a date.
export async function postOwnJson<T>(path: string, body: unknown, user: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export async function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  refuseWhileAsOf('PUT', path);
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
-- The history a statement taken as of a date reads: every change below is kept with the sheet's
-- today when it was made (set_on / made_on / added_on), so the figures as they stood at the end of a
-- date are those of the changes made while the sheet's today was on or before it. What was already
-- stored before this history was kept counts from the beginning of time (0001-01-01, or null).

-- The sheet's today when the person was added (null: from the beginning of time).
ALTER TABLE person ADD COLUMN added_on DATE;

-- Every rate set, oldest first: the rate in force for a grade and from-date as of a date is the
-- last one set for them on or before it.
CREATE TABLE rate_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    grade CHAR(1) NOT NULL,
    pct DECIMAL(19, 2) NOT NULL,
    from_date DATE,
    to_date DATE,
    set_on DATE NOT NULL
);
CREATE INDEX rate_history_sheet ON rate_history(sheet_id, id);
INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, set_on)
    SELECT sheet_id, grade, pct, from_date, to_date, DATE '0001-01-01' FROM rate;

-- Every dated setting value recorded, oldest first, and every policy date set (key policy-date,
-- no from-date, '' for none).
CREATE TABLE setting_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE,
    setting_value VARCHAR(40) NOT NULL,
    set_on DATE NOT NULL
);
CREATE INDEX setting_history_sheet ON setting_history(sheet_id, id);
INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)
    SELECT sheet_id, setting_key, from_date, setting_value, DATE '0001-01-01' FROM setting_value;
INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)
    SELECT id, 'policy-date', NULL, CAST(policy_date AS VARCHAR), DATE '0001-01-01' FROM sheet WHERE policy_date IS NOT NULL;

-- Every grade a person was given, oldest first: the first grade (no from-date) or a dated one.
CREATE TABLE person_grade_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    from_date DATE,
    grade CHAR(1) NOT NULL,
    set_on DATE NOT NULL
);
CREATE INDEX person_grade_history_sheet ON person_grade_history(sheet_id, person_id, id);
INSERT INTO person_grade_history (sheet_id, person_id, from_date, grade, set_on)
    SELECT sheet_id, id, NULL, grade, DATE '0001-01-01' FROM person;
INSERT INTO person_grade_history (sheet_id, person_id, from_date, grade, set_on)
    SELECT sheet_id, person_id, from_date, grade, DATE '0001-01-01' FROM person_grade;

-- Every retirement date a person was given, oldest first.
CREATE TABLE person_retirement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    from_date DATE,
    set_on DATE NOT NULL
);
CREATE INDEX person_retirement_sheet ON person_retirement(sheet_id, person_id, id);
INSERT INTO person_retirement (sheet_id, person_id, from_date, set_on)
    SELECT sheet_id, id, retired_from, DATE '0001-01-01' FROM person WHERE retired_from IS NOT NULL;

-- The sheet's today when a hold was added (null: from the beginning of time).
ALTER TABLE person_hold ADD COLUMN made_on DATE;

-- Every change to a claim's statement binding, oldest first: bound (with its figure, null: n/a) or
-- left unbound. A claim with no line on or before a date was unbound then.
CREATE TABLE claim_binding (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    claim_id BIGINT NOT NULL REFERENCES claim(id),
    stated BOOLEAN NOT NULL,
    stated_due DECIMAL(19, 2),
    set_on DATE NOT NULL
);
CREATE INDEX claim_binding_sheet ON claim_binding(sheet_id, claim_id, id);
INSERT INTO claim_binding (sheet_id, claim_id, stated, stated_due, set_on)
    SELECT sheet_id, id, TRUE, stated_due, DATE '0001-01-01' FROM claim WHERE stated;
